/**
 * Resolve the deployment base path (Next.js `basePath`) at runtime.
 *
 * Why this exists: Readest ships as a static export that can be served from
 * the site root (`/`) or from a sub-path (`/readest/` on GitHub Pages). The
 * browser resolves a *root-relative* URL like `/vendor/pdfjs/pdf.worker.min.mjs`
 * against the origin, never against the app's own sub-path — so on a sub-path
 * deployment those requests 404. (Symptom: importing a PDF fails with
 * "Failed to fetch dynamically imported module: .../vendor/pdfjs/pdf.worker.min.mjs".)
 *
 * Next.js injects the configured `basePath` into the client bundle as
 * `process.env.__NEXT_ROUTER_BASEPATH` — for a static export this is the
 * literal string (`''` or `'/readest'`), not `undefined`. We also fall back to
 * `<base href>` and finally to a relative path derived from the current
 * document location, so the helper keeps working outside Next.js (e.g. the
 * Tauri build, where the app is served from `file://`).
 */

/** The configured base path, normalized to '' or '/segment' (no trailing slash). */
export const getBasePath = (): string => {
  // Injected by next.config.mjs `env` at build time — the authoritative source
  // for static exports (Next 16 does not expose __NEXT_ROUTER_BASEPATH there).
  const fromConfig = process.env['NEXT_PUBLIC_BASE_PATH'];
  if (typeof fromConfig === 'string') {
    const trimmed = fromConfig.endsWith('/') ? fromConfig.slice(0, -1) : fromConfig;
    if (trimmed) return trimmed;
  }

  // Next.js injects this at build time for the client bundle.
  const fromNext = process.env['__NEXT_ROUTER_BASEPATH'];
  if (typeof fromNext === 'string' && fromNext) {
    return fromNext.endsWith('/') ? fromNext.slice(0, -1) : fromNext;
  }

  // Fallback: an explicit <base href="..."> in the document head.
  if (typeof document !== 'undefined') {
    const baseEl = document.querySelector('base');
    const href = baseEl?.getAttribute('href');
    if (href) {
      try {
        const url = new URL(href, location.href);
        const path = url.pathname.replace(/\/+$/, '');
        if (path) return path;
      } catch {
        // Malformed href — fall through to the location-based guess.
      }
    }
  }

  return '';
};

/**
 * Turn an app-root-relative path (`/vendor/x.js`) into a URL that resolves
 * correctly under the current deployment base path.
 *
 * `location.href` is used as the base so the result stays absolute (and thus
 * usable as a `Worker` script URL or a dynamic-import specifier).
 */
export const withBasePath = (appRootPath: string): string => {
  const base = getBasePath();
  const path = appRootPath.startsWith('/') ? appRootPath : `/${appRootPath}`;
  return new URL(base + path, location.href).href;
};
